"""Unit tests for risk.returns.log_returns (spine: simple returns)."""

from __future__ import annotations

import pytest

from mdata.types import Prices
from risk.returns import log_returns


def _sample_prices(contract_sample) -> Prices:
    data = contract_sample("mdata.Prices")
    return Prices(
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        closes={k: tuple(v) for k, v in data["closes"].items()},
    )


def test_sample_dates_follow_the_base_date(contract_sample):
    returns = log_returns(_sample_prices(contract_sample))
    assert returns.base_date == "2024-01-02"
    assert returns.dates == ("2024-01-03", "2024-01-04", "2024-01-05", "2024-01-08", "2024-01-09")
    assert returns.tickers == ("AAA", "BBB")


def test_sample_values_are_simple_returns(contract_sample):
    returns = log_returns(_sample_prices(contract_sample))
    assert returns.values["AAA"] == pytest.approx(
        (0.02, -1.0 / 102.0, 2.0 / 101.0, 1.0 / 103.0, -2.0 / 104.0), abs=1e-12
    )
    assert returns.values["BBB"] == pytest.approx(
        (0.01, 0.5 / 50.5, 0.0, 0.5 / 51.0, 0.5 / 51.5), abs=1e-12
    )


def test_two_dates_give_one_return():
    prices = Prices(dates=("2024-01-02", "2024-01-03"), tickers=("X",), closes={"X": (10.0, 8.0)})
    returns = log_returns(prices)
    assert returns.base_date == "2024-01-02"
    assert returns.dates == ("2024-01-03",)
    assert returns.values == {"X": pytest.approx((-0.2,))}


@pytest.mark.parametrize("dates", [(), ("2024-01-02",)])
def test_fewer_than_two_dates_raise(dates):
    prices = Prices(dates=dates, tickers=("X",), closes={"X": tuple(1.0 for _ in dates)})
    with pytest.raises(ValueError, match="two dates"):
        log_returns(prices)

